INSERT INTO lessons (id,skill_id,slug,title,body_json,zone_id,prerequisite_mission_id,first_mission_id,sort_order,status) VALUES (5003,5003,'estudo-decisoes-repeticoes','Decisões e repetições','{"introduction":"Estude comparações, if, elif, for, range e acumulação antes de iniciar as cinco batalhas deste bloco.","sections":[{"title":"Conceitos centrais","text":"Decisões e repetições conecta comparações, if, elif, for, range e acumulação. Entenda o fluxo dos dados, mantenha contratos claros e trate entradas vazias ou inválidas."},{"title":"Estratégia de resolução","text":"Leia a assinatura, identifique entradas e saída, quebre o problema em passos menores e teste limites antes de atacar."},{"title":"Aplicação profissional","text":"As últimas batalhas combinam múltiplas regras, validação e transformação de dados para aproximar o exercício de código real."}],"exampleCode":"total = 0\nfor valor in valores:\n    if valor > 0:\n        total += valor","keyPoints":["comparações, if, elif, for, range e acumulação","Contratos de entrada e saída","Casos extremos e legibilidade","Decomposição e testes"],"practiceObjectives":["1. Decisões e repetições I","2. Decisões e repetições II","3. Faixa tarifária","4. Múltiplos no intervalo","5. Relatório de paridade"],"pdfUrl":"/materials/python/zona-1-fundamentos.pdf","videoUrl":"https://learn.microsoft.com/en-us/shows/intro-to-python-development/","videoLabel":"Vídeo curto: Decisões e repetições","references":[{"label":"Tutorial oficial do Python","url":"https://docs.python.org/3/tutorial/"}]}',25,6010,6011,13,'published');
