INSERT INTO lessons (id,skill_id,slug,title,body_json,zone_id,prerequisite_mission_id,first_mission_id,sort_order,status) VALUES (5005,5006,'estudo-listas-sequencias','Listas, tuplas e sequências','{"introduction":"Estude índices, slices, cópias, tuplas e transformações antes de iniciar as cinco batalhas deste bloco.","sections":[{"title":"Conceitos centrais","text":"Listas, tuplas e sequências conecta índices, slices, cópias, tuplas e transformações. Entenda o fluxo dos dados, mantenha contratos claros e trate entradas vazias ou inválidas."},{"title":"Estratégia de resolução","text":"Leia a assinatura, identifique entradas e saída, quebre o problema em passos menores e teste limites antes de atacar."},{"title":"Aplicação profissional","text":"As últimas batalhas combinam múltiplas regras, validação e transformação de dados para aproximar o exercício de código real."}],"exampleCode":"ultimos = valores[-3:]\nprimeiro, *meio, ultimo = valores","keyPoints":["índices, slices, cópias, tuplas e transformações","Contratos de entrada e saída","Casos extremos e legibilidade","Decomposição e testes"],"practiceObjectives":["1. Listas, tuplas e sequências I","2. Listas, tuplas e sequências II","3. Rotação de lista","4. Janelas móveis","5. Intercalar sequências"],"pdfUrl":"/materials/python/zona-2-colecoes.pdf","videoUrl":"https://learn.microsoft.com/en-us/shows/intro-to-python-development/","videoLabel":"Vídeo curto: Listas, tuplas e sequências","references":[{"label":"Tutorial oficial do Python","url":"https://docs.python.org/3/tutorial/"}]}',26,6021,6022,1,'published');
