INSERT INTO lessons (id,skill_id,slug,title,body_json,zone_id,prerequisite_mission_id,first_mission_id,sort_order,status) VALUES (5009,5011,'estudo-assinaturas-flexiveis','Assinaturas flexíveis','{"introduction":"Estude parâmetros padrão, argumentos nomeados, *args e contratos antes de iniciar as cinco batalhas deste bloco.","sections":[{"title":"Conceitos centrais","text":"Assinaturas flexíveis conecta parâmetros padrão, argumentos nomeados, *args e contratos. Entenda o fluxo dos dados, mantenha contratos claros e trate entradas vazias ou inválidas."},{"title":"Estratégia de resolução","text":"Leia a assinatura, identifique entradas e saída, quebre o problema em passos menores e teste limites antes de atacar."},{"title":"Aplicação profissional","text":"As últimas batalhas combinam múltiplas regras, validação e transformação de dados para aproximar o exercício de código real."}],"exampleCode":"def totalizar(*valores, taxa=0):\n    return sum(valores) * (1 + taxa)","keyPoints":["parâmetros padrão, argumentos nomeados, *args e contratos","Contratos de entrada e saída","Casos extremos e legibilidade","Decomposição e testes"],"practiceObjectives":["1. Assinaturas flexíveis I","2. Assinaturas flexíveis II","3. Média ponderada","4. Configuração segura","5. Faixas opcionais"],"pdfUrl":"/materials/python/zona-3-funcoes.pdf","videoUrl":"https://learn.microsoft.com/en-us/shows/intro-to-python-development/","videoLabel":"Vídeo curto: Assinaturas flexíveis","references":[{"label":"Tutorial oficial do Python","url":"https://docs.python.org/3/tutorial/"}]}',27,6042,6043,1,'published');
