INSERT INTO lessons (id,skill_id,slug,title,body_json,zone_id,prerequisite_mission_id,first_mission_id,sort_order,status) VALUES (5014,5017,'estudo-formatos-padroes','JSON, regex e datas','{"introduction":"Estude serialização, expressões regulares e validação de formatos antes de iniciar as cinco batalhas deste bloco.","sections":[{"title":"Conceitos centrais","text":"JSON, regex e datas conecta serialização, expressões regulares e validação de formatos. Entenda o fluxo dos dados, mantenha contratos claros e trate entradas vazias ou inválidas."},{"title":"Estratégia de resolução","text":"Leia a assinatura, identifique entradas e saída, quebre o problema em passos menores e teste limites antes de atacar."},{"title":"Aplicação profissional","text":"As últimas batalhas combinam múltiplas regras, validação e transformação de dados para aproximar o exercício de código real."}],"exampleCode":"dados = json.loads(texto)\nvalido = re.fullmatch(padrao, valor)","keyPoints":["serialização, expressões regulares e validação de formatos","Contratos de entrada e saída","Casos extremos e legibilidade","Decomposição e testes"],"practiceObjectives":["1. JSON, regex e datas I","2. JSON, regex e datas II","3. Normalizar telefones","4. Agrupar por mês","5. Mesclar configurações JSON"],"pdfUrl":"/materials/python/zona-4-confiabilidade.pdf","videoUrl":"https://learn.microsoft.com/en-us/shows/more-python-for-beginners/","videoLabel":"Vídeo curto: JSON, regex e datas","references":[{"label":"Tutorial oficial do Python","url":"https://docs.python.org/3/tutorial/"}]}',28,6068,6069,7,'published');
