INSERT INTO lessons (id,skill_id,slug,title,body_json,zone_id,prerequisite_mission_id,first_mission_id,sort_order,status) VALUES (5020,5024,'estudo-iteracao-preguicosa','Iteradores e geradores','{"introduction":"Estude protocolo iterador, yield, pipelines preguiçosos e memória antes de iniciar as cinco batalhas deste bloco.","sections":[{"title":"Conceitos centrais","text":"Iteradores e geradores conecta protocolo iterador, yield, pipelines preguiçosos e memória. Entenda o fluxo dos dados, mantenha contratos claros e trate entradas vazias ou inválidas."},{"title":"Estratégia de resolução","text":"Leia a assinatura, identifique entradas e saída, quebre o problema em passos menores e teste limites antes de atacar."},{"title":"Aplicação profissional","text":"As últimas batalhas combinam múltiplas regras, validação e transformação de dados para aproximar o exercício de código real."}],"exampleCode":"def lotes(itens, tamanho):\n    for inicio in range(0, len(itens), tamanho):\n        yield itens[inicio:inicio+tamanho]","keyPoints":["protocolo iterador, yield, pipelines preguiçosos e memória","Contratos de entrada e saída","Casos extremos e legibilidade","Decomposição e testes"],"practiceObjectives":["1. Iteradores e geradores I","2. Iteradores e geradores II","3. Gerador de lotes","4. Fibonacci preguiçoso","5. Pipeline de geradores"],"pdfUrl":"/materials/python/zona-5-objetos.pdf","videoUrl":"https://learn.microsoft.com/en-us/shows/more-python-for-beginners/","videoLabel":"Vídeo curto: Iteradores e geradores","references":[{"label":"Tutorial oficial do Python","url":"https://docs.python.org/3/tutorial/"}]}',29,6099,6100,19,'published');
